-- DAT_details: item display text (name/longname/description/valid races) extracted from client DAT data.
-- This is NOT part of the private-server schema - it is an addition owned by this wiki extension,
-- kept in its own table/file so it survives re-syncs of item_basic/item_equipment/item_weapon from upstream.
-- itemid matches item_basic.itemid; for server custom items (id >= 50000) the display data has already
-- been resolved from the old replacement map at generation time, so no indirection is needed at query time.
-- Generated from includes/helpers/data/FFXIPackageHelper_ItemDetails.php - jobs/level/flags were intentionally
-- NOT migrated here since they already exist as decodable columns on item_equipment/item_basic.

DROP TABLE IF EXISTS `dat_details`;
CREATE TABLE `dat_details` (
  `itemid` int(10) unsigned NOT NULL,
  `name` varchar(255) NOT NULL DEFAULT '',
  `longname` varchar(255) NOT NULL DEFAULT '',
  `descr` text NOT NULL,
  `races` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`itemid`)
) DEFAULT CHARSET=utf8mb4;

LOCK TABLES `dat_details` WRITE;
INSERT INTO `dat_details` (`itemid`, `name`, `longname`, `descr`, `races`) VALUES
